operation.add:
case 9:
          require_once(modification("vendor/phpmailer/phpmailer/PHPMailerAutoload.php"));

          $mail = new PHPMailer;

          $mail->isSMTP();
          $mail->SMTPDebug = 0;
          $mail->Debugoutput = 'html';
          $mail->Host = "smtp.epdvr.com.br";
          $mail->SMTPAutoTLS = false;
          $mail->Port = '25';
          $mail->SMTPAuth = false;

          $mail->setFrom($this->sEmailFrom[0], $this->sEmailFrom[1]);
          $mail->addAddress($this->sEmailTo);

          $mail->Subject = $this->sSubject;
          $mail->msgHTML($this->sMsg);

          $mail->send();

        break;
